#!/usr/bin/env bash

main() {
    local -A b1=([name]=one [size]=0 [amount]=0)
    local -A b2=([name]=two [size]=0 [amount]=0)
    b1[size]=$1
    b2[size]=$2
    local goal=$3 start=$4

    validate ${b1[size]} ${b2[size]} $goal

    case $start in
        one) solve b1 b2 $goal ;;
        two) solve b2 b1 $goal ;;
        *) echo "invalid start bucket" >&2; exit 1 ;;
    esac
}

validate() {
    local a=$1 b=$2 goal=$3

    # the goal amount must fit in a single bucket
    local max; (( a > b )) && max=$a || max=$b
    if (( goal > max )); then
        echo "invalid goal: too big" >&2
        exit 1
    fi

    # if the buckets are not relatively prime, then
    # the goal must be divisible by the greatest
    # common divisor of the buckdets
    local gcd=$(gcd $a $b)
    if (( gcd > 1 && (goal % gcd) != 0 )); then
        echo "invalid goal: unsatisfiable" >&2
        exit 1
    fi
}

gcd() {
    local -i a=$1 b=$2
    if (( b > 0 )); then
        gcd $b $((a % b))
    else
        echo $a
    fi
}

solve() {
    local -n start=$1 other=$2
    local -i goal=$3 moves

    fill start
    moves=1

    ((other[size] == goal)) && {
        fill other
        (( moves++ ))
    }

    while true; do
        if (( start[amount] == goal )); then
            output $moves ${start[name]} ${other[amount]}
            return
        elif (( other[amount] == goal )); then
            output $moves ${other[name]} ${start[amount]}
            return
        fi

        if   is_empty start; then fill  start
        elif is_full  other; then empty other
        else                      pour  from start to other
        fi
        (( moves++ ))
    done
}

output() {
    echo "moves: $1, goalBucket: $2, otherBucket: $3"
}

is_empty() {
    local -n bucket=$1
    (( bucket[amount] == 0 ))
}

is_full() {
    local -n bucket=$1
    (( bucket[amount] == bucket[size] ))
}

capacity() {
    local -n bucket=$1
    echo $(( bucket[size] - bucket[amount] ))
}

fill() {
    local -n bucket=$1
    bucket[amount]=${bucket[size]}
}

empty() {
    local -n bucket=$1
    bucket[amount]=0
}

pour() {
    # have to be careful not to reuse a variable name from
    # anywhere up the stack.
    local -n _b1_=$2 _b2_=$4
    local b1_amt=${_b1_[amount]}
    local b2_amt=${_b2_[amount]} 
    local b2_cap=$(capacity _b2_)

    # determine the amount to pour: minimum of
    # b1's current amount and b2's current capacity
    local amount
    (( b1_amt < b2_cap )) && amount=$b1_amt || amount=$b2_cap
    _b1_[amount]=$(( b1_amt - amount ))
    _b2_[amount]=$(( b2_amt + amount ))
}

main "$@"

#!/usr/bin/env bash

main() {
    local -l question=$1            # lower case
    question=${question#what is}    # remove prefix words
    question=${question%?}          # remove trailing "?"

    [[ -n $question ]] || die "syntax error"

    subst question
    evaluate question
}

subst() {
    local -n q=$1
    while [[ $q == *[[:alpha:]]* ]]; do
        prev=$q

        q=${q//plus/+}
        q=${q//minus/-}
        q=${q//multiplied by/*}
        q=${q//divided by/\/}

        if [[ $prev == "$q" ]]; then
            # we have letters, but did not match a valid op
            die "unknown operation"
        fi
    done
}

evaluate() {
    local -n q=$1
    while true; do
        read -r a op b rest <<<"$q"

        isInt "$a" || die "syntax error"

        if [[ -z $op ]]; then
            echo "$a"
            return
        fi

        isInt "$b" || die "syntax error"
        isOp "$op" || die "syntax error"

        if [[ -n $rest ]]; then
            q="$(( a $op b )) $rest"
        else
            q=$(( a $op b ))
        fi
    done
}

shopt -s extglob

isInt() { [[ $1 == ?(-)+([[:digit:]]) ]]; }
isOp()  { [[ $1 == [-+*/] ]]; }
die()   { echo "$*" >&2; exit 1; }

main "$@"

#!/usr/bin/env bash

# assume proper rolls 1<=d<=6

main() {
    local category=$1; shift

    case $category in
        ones)   xs 1 $@ ;;
        twos)   xs 2 $@ ;;
        threes) xs 3 $@ ;;
        fours)  xs 4 $@ ;;
        fives)  xs 5 $@ ;;
        sixes)  xs 6 $@ ;;
        "full house")      full_house $@ ;;
        "four of a kind")  four_of_a_kind $@ ;;
        "little straight") straight 1 $@ ;;
        "big straight")    straight 2 $@ ;;
        yacht)             yacht $@ ;;
        choice)            sum $@ ;;
    esac
}

xs() {
    local -i target=$1; shift
    local -i count=0 die
    for die; do
        (( die == target )) && (( count += 1 ))
    done
    echo $(( target * count ))
}

sum() {
    local -i sum=0 die
    for die; do
        (( sum += die ))
    done
    echo $sum
}


# the first parameter is an "inout" array nameref
group() {
    local -n ary=$1; shift
    ary=()
    local -i die
    for die; do
        (( ary[die] += 1 ))
    done
}

yacht() {
    local -a grp
    group grp $@
    # if the size of the array is 1, then all dice the same
    (( ${#grp[@]} == 1 )) && echo 50 || echo 0
}

full_house() {
    local -a grp
    group grp $@
    if (( ${#grp[@]} != 2 )); then
        echo 0
    else
        local -i die
        for die in ${!grp[@]}; do
            case ${grp[die]} in
                2|3) sum $@ ;;
                *) echo 0 ;;
            esac
            return
        done
    fi
}

four_of_a_kind() {
    local -a grp
    local -i die
    group grp $@
    for die in ${!grp[@]}; do
        if [[ ${grp[die]} == [45] ]]; then
            echo $(( die * 4 ))
            return
        fi
    done
    echo 0
}

straight() {
    local -i start=$1; shift
    local -i cmp
    (( start == 1 )) && cmp=12345 || cmp=23456

    # calling out to sort, might as well use paste
    local dice=$(printf "%d\n" "$@" | sort -n | tr -d \\n)

    (( dice == cmp )) && echo 30 || echo 0
}


main "$@"
